text:
{
"opening": "This release focuses on expanding locale coverage and correcting localization errors in existing Slavic and Nordic languages. It introduces new time granularity support and humanization capabilities for specific regions while fixing pluralization and ordinal formatting issues.",
"requirements": [
{
"id": "m01",
"text": "The Russian locale must correctly format the plural form for the 'seconds' unit in humanized time strings."
},
{
"id": "m02",
"text": "The Indonesian locale must recognize and humanize timeframes expressed in quarters and weeks."
},
{
"id": "m03",
"text": "The Russian locale must support quarter granularity when generating humanized time representations."
},
{
"id": "m06",
"text": "The library must provide a Kazakh locale implementation, and the Urdu locale must be available for use."
},
{
"id": "m08",
"text": "The Arrow class and base Locale interface must expose functionality to dehumanize time strings for supported Slavic locales."
},
{
"id": "m09",
"text": "The Czech and Slovak locales must support the dehumanization of time strings back into datetime objects or relative deltas."
},
{
"id": "m14",
"text": "Norwegian locales must append a period after the day number in ordinal date formats, and Portuguese ordinals must remain unaffected by this change."
}
],
"closing": "Please ensure all public API behaviors described above are verified before merging."
}
